import copy,datetime,functools,hashlib,itertools,json,os,pathlib,platform,resource,signal,subprocess,sys,tempfile,time
START=time.monotonic();resource.setrlimit(resource.RLIMIT_CPU,(120,120));resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30));signal.alarm(120)
ROOT=pathlib.Path(os.environ.get('RULE30_REPLAY_ROOT','/home/ryan/rule30-lab'))
OUT=pathlib.Path(os.environ.get('RULE30_REPLAY_OUTPUT',str(ROOT/'results/problem1/20260905_critical_cost_verification.json')))
def sha(b):return hashlib.sha256(b).hexdigest()
def canon(o):return json.dumps(o,sort_keys=True,separators=(',',':')).encode()
def spaced(o):return json.dumps(o,sort_keys=True).encode()
inputs={}
def read(p):
 b=(ROOT/p).read_bytes();inputs[p]=sha(b);return json.loads(b)
primary=read('results/problem1/20260905_critical_cost_primary.json');ind=read('results/problem1/20260905_critical_cost_independent.json');m=ind['result_summary']
probe_path='results/problem1/20260905_born_suffix_kernel_probe.json';probe=read(probe_path)
def check_inputs(mapping):
 for p,h in mapping.items():
  if p=='probe_tmp':p=probe_path
  actual=sha((ROOT/p).read_bytes());assert actual==h,(p,actual,h);inputs[p]=actual
check_inputs(primary['inputs']);check_inputs(ind['inputs'])
assert sha(primary['source_text'].encode())==primary['result_hashes']['integrator_sha256']
assert sha(spaced(primary['result_summary']))==primary['result_hashes']['result_summary_sha256']
assert sha(ind['source_text'].encode())==ind['result_hashes']['source_sha256']
assert sha(canon(m))==ind['result_hashes']['result_summary_sha256']
for name,original in primary['original_run_records'].items():
 r=copy.deepcopy(original)
 if name=='sharpness':r['result_summary']['family']={int(k):v for k,v in r['result_summary']['family'].items()}
 assert sha(json.dumps(r,indent=1,sort_keys=True).encode())==primary['result_hashes']['payloads'][name],name
 assert sha(r['source_text'].encode())==r['result_hashes']['source_sha256']==primary['result_hashes']['sources'][name]
 assert sha(spaced(r['result_summary']))==r['result_hashes']['result_summary_sha256'],name
 check_inputs(r.get('provenance',{}).get('inputs',{}))
reference='src/python/rule30_research_reference.py';inputs[reference]=sha((ROOT/reference).read_bytes());assert inputs[reference]=='358bdc07904e77080eb78b67bdd8da25822d6b51f1a91b58b5313dfe461c1d01'
def T(x):return x^((x<<1)|(x<<2))
def A(x):return T(x)>>2
def G(g,x):return T(x) if g=='t' else T(x)^1 if g=='u' else T(2*x+1)>>1
@functools.lru_cache(None)
def Ap(x,s):
 for _ in range(s):x=A(x)
 return x
def I(x):return int(x%64 in (0,5))
def J(x):return I(A(x))+I(x>>2)
def D(x,s):return sum(I(Ap(x>>(2*d),s-1-d)) for d in range(s))
def pref(root,w):
 v=[root]
 for g in w:v.append(G(g,v[-1]))
 return v
def omega(x,g):return int((x%16,g) in [(0,'t'),(1,'u')])
def H(root,w):return ''.join('tupp'[x%4] for x in pref(root,w)[1:])
def W(root,w):return sum(omega(x,g) for x,g in zip(pref(root,w),w))
def gate(x):return 'u' if x%16==7 else 't' if x%16==11 else None
def orbit(x,s):
 xs=[x];word=''
 for _ in range(s):
  g=gate(x);assert g;word+=g;x=G(g,A(x));xs.append(x)
 return xs,word
def beta(xs,word,s):
 return sum(omega(Ap(xs[t-1],s-t+1),word[t-1] if t==s else 'tupp'[Ap(xs[t],s-t-1)%4]) for t in range(1,s+1))
# Exact same finite row domain/order as cell record; costs pulled from original prefixes.
hashrows=hashlib.sha256();nrows=words=0
for phase,root in [('p',3),('u',1)]:
 for n in range(9):
  for letters in itertools.product('tup',repeat=n):
   w=''.join(letters);vs=pref(root,w);x=vs[-1];words+=1
   for s in range(max(1,n-4),n+4):
    c=sum(I(Ap(v,s-1)) for v in vs[1:]);ds=D(x,s);pad=max(s-n-1,0)
    assert c==ds-pad
    hashrows.update(canon([phase,n,w,x,s,c,ds,pad])+b'\n');nrows+=1
assert words==m['word_count']==19682 and nrows==m['C_D_cases']==157098
assert hashrows.hexdigest()==m['C_D_row_sha256']
assert primary['original_run_records']['final']['result_summary']['D_grid']=={'tested':nrows,'mismatches':0,'domain':'n=0..8 both phases, s=max(1,n-4)..n+3'}
for phase,root in [('p',3),('u',1)]:
 level={root}
 for k in range(1,6):
  assert sorted(level)==m['base_frontiers_k1_to5'][phase+str(k)]
  assert not any(I(x) for x in level) and {A(x) for x in level}<=level
  level={G(g,x) for x in level for g in 'tup'}
pre={str(z):{g:[x for x in range(64) if G(g,x)%64==z] for g in 'tup'} for z in [0,5]}
assert pre==m['charge_preimage_table_mod64']
assert [J(q) for q in range(256)]==m['boundary_J_table_mod256']
cyc=[3205]
for _ in range(4):cyc.append(A(cyc[-1]))
assert cyc==m['sharpness']['A_cycle']==[3205,3558,3214,3564,3205]
examples=endpoint_memberships=0
for row in m['schedule_groups']:
 s=row['s'];q=row['q'];xs,word=orbit(q,s+1);assert word==row['branches']
 ds=D(q,s);b=beta(xs,word,s);boundary=[{'t':t,'quotient_mod256':(xs[t]>>(2*(s-t-2)))%256,'J':J(xs[t]>>(2*(s-t-2)))} for t in range(s-1)]
 assert (ds,b,ds+b)==(row['D'],row['beta'],row['W_plus_padding'])
 assert boundary==row['boundary_terms'] and sum(t['J'] for t in boundary)==ds+b
 for x in row['endpoints']:
  assert x%(1<<(2*s+4))==q;assert orbit(x,s+1)[1]==word;endpoint_memberships+=1
 for ex in row['examples']:
  root=3 if ex['phase']=='p' else 1;w=ex['word_from_zero'][1:];n=len(w);x=pref(root,w)[-1]
  assert x==ex['endpoint'] and n==ex['n'];fw=w;hw=w;exxs,eword=orbit(x,s+1)
  for t in range(s):fw=H(root,fw)+eword[t];hw=H(root,hw)
  pad=max(s-n-1,0);assert pref(root,fw)[-1]==exxs[s]
  assert (W(root,hw),W(root,fw),pad)==(ex['C'],ex['W'],ex['padding'])
  assert W(root,fw)+pad==ds+b;examples+=1
assert len(m['schedule_groups'])==43 and sum(r['histories'] for r in m['schedule_groups'])==665
for key,row in primary['original_run_records']['sharpness']['result_summary']['family'].items():
 s=int(key);w='upupt'+'t'*s;vs=pref(3,w);hw=w
 for _ in range(s):hw=H(3,hw)
 costs=[omega(x,g) for x,g in zip(pref(3,hw),hw)]
 assert w==row['word'] and hex(vs[-1])==row['endpoint_hex'] and len(w)==row['n']==s+5
 assert costs[:4]==row['first4']==[0]*4 and costs[4]==row['pos5']==1
 assert sum(costs)==row['C'] and D(vs[-1],s)==row['D'] and sum(costs)-D(vs[-1],s)==1
probe_rows={r['word']:r for level in probe['result_summary']['levels'] for r in level['rows']};psiages=0
for row in primary['original_run_records']['psi']['detail']:
 xs,word=orbit(row['x0'],len(row['word']));assert word==row['word'] and xs==probe_rows[word]['states']
 for age in row['ages']:
  s=age['s'];val=D(xs[0],s)+beta(xs,word,s);bs=sum(J(xs[t]>>(2*(s-t-2))) for t in range(s-1))
  assert val==bs==age['Psi']==age['boundary'] and age['match'];psiages+=1
summary={'completed':True,'failures':[],'C_D_rows_recomputed':nrows,'C_D_row_sha256':hashrows.hexdigest(),'ordinary_words':words,'schedule_groups_checked':43,'recorded_endpoint_memberships_checked':endpoint_memberships,'recorded_history_examples_checked':examples,'sharpness_family_ages':[1,5,9,13],'psi_probe_chains':4,'psi_ages_including_terminal':psiages,'base_frontiers_checked':10,'J_table_modulus':256,'original_payload_source_summary_input_hashes_verified':True,'immutable_reference_verified':True}
source=pathlib.Path(__file__).read_bytes()
record={'experiment_id':'problem1-critical-cost-portable-verification-20260905','timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'question':'problem1','hypothesis':'Independent packed replay and portable provenance reproduce the declared critical-cost certificates.','backend':'python-packed-prefix-cost-and-direct-history-replay','parameters':{'C_D_domain':'both phases; n0..8; s=max(1,n-4)..n+3','group_scope':'all43 stored groups, listed endpoint memberships and listed history examples; no full forced-row hash replay','sharpness_ages':[1,5,9,13],'psi_scope':'four stored probe chains through terminal age','cpu_seconds_limit':120,'wall_seconds_limit':120,'address_space_bytes':1<<30},'hardware':{'machine':platform.machine(),'cpu_count':os.cpu_count(),'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss},'software':{'python':sys.version,'platform':platform.platform()},'runtime_seconds':time.monotonic()-START,'inputs':inputs,'source_text':source.decode(),'result_hashes':{'source_sha256':sha(source),'result_summary_sha256':sha(canon(summary))},'result_summary':summary,'status':'finite-exhaustive','interpretation':'All declared checks pass. The C/D row hash matches the cell record; Muse contributes aggregate agreement, not a separate matching row hash.','proof_scope':'Finite certificate verification only; all-depth arguments are in the accompanying proof note.','limitations':['No exhaustive verification beyond the declared word/age domain.','Stored schedule groups are checked; the complete665 forced-row hash is not regenerated.','No return descent, occurrence exclusion or Problem1 proof.'],'serialization_notes':'Original Muse summaries use spaced sort_keys JSON; sharpness family age keys restored to int before original summary/payload reconstruction. Muse probe_tmp maps to the committed born_suffix_kernel_probe record.'}
with tempfile.NamedTemporaryFile('w',dir=OUT.parent,delete=False) as f:
 json.dump(record,f,sort_keys=True,indent=2);f.write('\n');f.flush();os.fsync(f.fileno());tmp=f.name
os.replace(tmp,OUT);print(json.dumps(summary))
